using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class AuditRolePrefabs {
 static Bounds BoundsOf(Transform model,Transform space){bool first=true;var b=new Bounds();foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var m=new Mesh();r.BakeMesh(m,false);foreach(var v in m.vertices){var p=space.InverseTransformPoint(r.transform.TransformPoint(v));if(first){b=new Bounds(p,Vector3.zero);first=false;}else b.Encapsulate(p);}Object.DestroyImmediate(m);}return b;}
 public static object Main(string ids){if(EditorApplication.isPlaying)throw new Exception("Edit required");var rows=new List<object>();foreach(var id in ids.Split(',')){string folder="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+id;var g=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/"+id+".prefab"));try{var animator=g.GetComponentInChildren<Animator>();animator.enabled=false;var samples=new List<object>();float minBottom=100,maxBottom=-100,maxHeight=0;foreach(var clip in animator.runtimeAnimatorController.animationClips.Distinct())foreach(float phase in new[]{0f,.5f,.99f}){clip.SampleAnimation(animator.gameObject,clip.length*phase);var b=BoundsOf(animator.transform,g.transform);minBottom=Mathf.Min(minBottom,b.min.y);maxBottom=Mathf.Max(maxBottom,b.min.y);maxHeight=Mathf.Max(maxHeight,b.size.y);samples.Add(new{state=clip.name,phase,height=b.size.y,bottom=b.min.y});}rows.Add(new{id,clips=animator.runtimeAnimatorController.animationClips.Length,minBottom,maxBottom,maxHeight,normalizationVerified=minBottom>-.04f&&maxBottom<.05f&&maxHeight<3,samples});}finally{Object.DestroyImmediate(g);}}return new{items=rows};}
}
